def _export_body(snapshot):
    """The checksum-covered body of an export document."""
    return {
        "format": _EXPORT_FORMAT,
        "seq": snapshot["seq"],
        "span": snapshot["span"],
        "capacity": snapshot["capacity"],
        "now": snapshot["now"],
